(function(){'use strict';
/* Experiment Solver Database generator — jahdb-experiment-solver-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-EXPSOLV-';
var SRC='public';
var RECORD_KIND='experiment solver record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"The Scientific Method","brief":"The systematic cycle of observation, hypothesis, prediction, experiment, and revision behind reliable knowledge.","points":["Observations spark questions; hypotheses propose testable explanations.","Predictions must be falsifiable — capable of being proven wrong.","Controlled experiments isolate the effect being tested.","Results refine or replace the hypothesis; the cycle repeats."],"examples":["Testing whether fertilizer increases plant growth with treated and untreated pots.","Dropping objects of different masses to test Galileo's prediction."],"history":["Ibn al-Haytham (1021) and later Bacon, Galileo, and Newton formalized experimental science.","Popper's falsifiability (1934) gave the method its philosophical backbone."],"uses":["Every laboratory science runs on this cycle.","Engineers adapt it for troubleshooting and design validation.","Citizen scientists apply it to local questions."],"qa":[["Is the scientific method one fixed recipe?","No — it's a family of practices adapted to each field's constraints."],["What makes a good hypothesis?","Testable, specific, and falsifiable — predicting a measurable outcome."],["Can science prove things?","It disproves and corroborates; absolute proof belongs to mathematics."]]},{"title":"Hypothesis Formation","brief":"Crafting testable explanations — the creative leap that starts every experiment.","points":["Good hypotheses predict specific, measurable outcomes.","Null hypotheses state 'no effect' — the statistical default to beat.","Alternative hypotheses state the expected effect and its direction.","Hypotheses come from theory, observation, analogy, and curiosity."],"examples":["Hypothesizing that warmer water dissolves sugar faster.","A null hypothesis: the new drug performs no better than placebo."],"history":["19th-century physiologists like Bernard made hypothesis-testing explicit.","Fisher's 1920s statistics gave hypotheses rigorous testing machinery."],"uses":["Researchers frame grant proposals around sharp hypotheses.","Product teams A/B test hypotheses about user behavior.","Students learn science by forming and testing their own."],"qa":[["Hypothesis vs theory?","A hypothesis is a single testable prediction; a theory is a broad confirmed framework."],["Can I have multiple hypotheses?","Yes — strong inference tests competing hypotheses simultaneously."],["What if my hypothesis is wrong?","That's success — falsification is how science advances."]]},{"title":"Experimental Design Basics","brief":"Planning experiments so results actually answer the question — structure before data.","points":["Define the research question precisely before touching equipment.","Identify treatments, controls, and the response variable.","Plan replication — how many independent repeats.","Anticipate confounders and block or randomize against them."],"examples":["Planning pot positions randomly so sunlight differences don't bias plant growth.","Deciding on 30 mice per group before a drug study begins."],"history":["Fisher's Rothamsted work (1920s-30s) founded modern experimental design.","His 'Design of Experiments' (1935) remains the bible."],"uses":["Every credible lab study starts with a design.","Industry R&D uses DOE to optimize processes efficiently.","Clinical trials are experiments designed under regulation."],"qa":[["What's the biggest design mistake?","Too few replicates — underpowered studies waste everything."],["Do I need statistics before starting?","Yes — power analysis sets sample size before you commit."],["Can I change the design mid-way?","Only with pre-planned adaptive rules; ad-hoc changes bias results."]]},{"title":"Control Groups","brief":"The untreated comparison that lets experiments isolate cause from coincidence.","points":["Controls experience everything except the treatment.","Positive controls verify the experiment can detect an effect.","Negative controls verify no effect appears without treatment.","Without controls, you can't separate treatment effects from time, placebo, or environment."],"examples":["A drug trial's placebo arm as the control group.","Unfertilized plots controlling a fertilizer experiment."],"history":["19th-century medicine adopted controls slowly; 1948's streptomycin trial set the RCT standard.","Agricultural field trials pioneered controls in the 1920s-30s."],"uses":["Clinical trials, psychology, and agriculture all require controls.","Manufacturing trials compare new settings against current ones.","Education research tests interventions against business-as-usual classes."],"qa":[["What is a placebo control?","An inert treatment controlling for expectation effects."],["Do all experiments need controls?","All causal claims do — the form varies by field."],["Historical controls?","Weaker than concurrent — times change; use when randomization is impossible."]]},{"title":"Independent, Dependent, and Controlled Variables","brief":"The three roles every variable plays — what you change, what you measure, what you hold steady.","points":["Independent variable: what the experimenter manipulates.","Dependent variable: the measured outcome.","Controlled variables: held constant to prevent confounding.","Operational definitions specify exactly how each is measured."],"examples":["Fertilizer amount (independent) vs plant height (dependent), with light and water controlled.","Drug dose vs blood pressure, controlling diet and age."],"history":["Mill's 19th-century methods of induction formalized variable control.","Fisher's blocking (1920s) gave controlled variables statistical treatment."],"uses":["Lab notebooks record all three for every run.","Protocols specify control tolerances explicitly.","Reviewers check variable control first when judging validity."],"qa":[["What is a confounding variable?","An uncontrolled variable correlated with the treatment — it mimics effects."],["Can a variable be both?","In chains of causation, one experiment's dependent is the next's independent."],["How many variables can I test?","Factorial designs test several efficiently — one-at-a-time wastes runs."]]},{"title":"Randomization","brief":"Letting chance assign treatments — the shield against hidden bias.","points":["Random assignment balances known and unknown confounders on average.","Randomize the order of runs to defeat time trends and drift.","Use proper random number generators, not haphazard 'picking'.","Randomization justifies the statistical tests that follow."],"examples":["Drawing treatment assignments from a random number table for field plots.","Shuffling run order so morning-vs-afternoon effects average out."],"history":["Fisher insisted on randomization at Rothamsted in the 1920s.","The 1948 British streptomycin trial made randomized trials the medical gold standard."],"uses":["Clinical trials randomize patients to arms.","Agricultural trials randomize plot layouts.","Industrial DOE randomizes run order."],"qa":[["Is haphazard good enough?","No — humans randomize badly; use real random numbers."],["What about small samples?","Randomize anyway, and consider blocking to force balance."],["Randomize or match?","Both — match/block on key variables, randomize within."]]},{"title":"Blinding and Placebos","brief":"Hiding treatment assignments so expectations can't warp results.","points":["Single-blind: subjects don't know; double-blind: researchers don't either.","Placebos control for the psychology of being treated.","Blinding prevents biased measurement and coaxing.","Unblind only after analysis plans are locked."],"examples":["Neither patient nor doctor knowing who got the drug versus sugar pill.","A taste test with coded samples hiding brand identities."],"history":["18th-century blinded tests (like Franklin's mesmerism commission) pioneered the idea.","1950s-60s medicine made double-blind RCTs mandatory for drug approval."],"uses":["Drug trials, psychology, and food science blind routinely.","Peer review is often blinded to reduce prestige bias.","Judges of competitions use blind evaluation."],"qa":[["Can you blind everything?","No — surgery and obvious treatments need workarounds like sham procedures."],["What breaks blinding?","Side effects that reveal the active treatment."],["Is blinding dishonest?","No — participants consent to possibly receiving placebo."]]},{"title":"Sample Size and Statistical Power","brief":"How many measurements you need — too few wastes the experiment, too many wastes resources.","points":["Power is the probability of detecting a real effect — aim for 80%+.","Effect size, variability, and significance level set the required n.","Power analysis before the experiment prevents futile underpowered studies.","Bigger isn't always better — oversized studies waste money and subjects."],"examples":["Calculating 64 patients per arm to detect a 10-point blood-pressure drop.","A pilot study's variance estimate feeding the full trial's power calc."],"history":["Neyman and Pearson's 1930s framework made power calculable.","Cohen's 1960s effect-size conventions popularized power analysis."],"uses":["Grant reviewers demand power justifications.","Ethics boards reject underpowered animal and human studies.","Industry sizes validation studies by power."],"qa":[["What is p-hacking?","Testing repeatedly until something is 'significant' — it manufactures false positives."],["Can I add subjects if not significant?","Only with pre-planned adaptive designs; otherwise it inflates false positives."],["Rule of thumb for n?","No substitute for calculation — but n=30 is a folk minimum for rough work."]]},{"title":"Replication","brief":"Repeating experiments to separate real effects from flukes — the heart of credibility.","points":["Direct replication repeats the exact procedure.","Conceptual replication tests the same idea differently.","Independent replication by other labs is the gold standard.","The replication crisis showed how many findings don't replicate."],"examples":["Three independent labs testing the same catalyst's claimed efficiency.","Re-running last month's assay with fresh reagents to confirm."],"history":["1930s-50s statistics formalized replication requirements.","The 2010s replication crisis (psychology, medicine) forced reforms."],"uses":["Journals now encourage registered replications.","Industry validates processes with replicate runs.","Regulators require replicate data for approvals."],"qa":[["How many replicates?","At least 3 for lab work; more for noisy systems — power analysis decides."],["Technical vs biological replicates?","Biological (independent samples) count; technical repeats don't."],["What if it won't replicate?","Check methods, then consider the original was a false positive."]]},{"title":"Pilot Studies","brief":"Small trial runs that de-risk the big experiment — rehearse before performing.","points":["Pilots test procedures, timing, and equipment on a small scale.","They estimate variability for power calculations.","They reveal practical problems — recruitment, handling, measurement issues.","Pilot data shouldn't be folded into the main results."],"examples":["Running 5 patients through a trial protocol to find bottlenecks.","A 10-plot field pilot testing a new sampling method."],"history":["Medical and agricultural research formalized pilots in the mid-1900s.","The 2000s-10s made pilot funding a standard grant category."],"uses":["Trialists pilot recruitment and procedures.","Manufacturers run pilot plants before full scale.","Survey researchers pilot questionnaires."],"qa":[["Is a pilot publishable?","As a feasibility study, yes — labeled as pilot."],["How big should a pilot be?","Big enough to test logistics — 10% of full scale is typical."],["Can pilots test hypotheses?","Only exploratorily — they're underpowered by design."]]},{"title":"Laboratory Safety","brief":"The practices that keep experimenters alive — because labs concentrate hazards.","points":["Risk assessments precede every new procedure.","PPE, fume hoods, and eyewash are the last lines of defense.","Chemical inventories, SDSs, and segregation prevent surprises.","Emergency plans — spills, fires, exposures — must be rehearsed."],"examples":["A risk assessment flagging a pyrophoric reagent's handling plan.","A fume hood containing a reaction's toxic vapors."],"history":["1940s-70s lab disasters drove modern safety culture.","OSHA's 1990 Lab Standard mandated chemical hygiene plans."],"uses":["Every research and teaching lab operates under safety programs.","Safety officers audit and train continuously.","Incident investigations improve procedures."],"qa":[["Most common lab injury?","Cuts, chemical splashes, and thermal burns — basics matter."],["Can I work alone?","With hazardous materials, generally no — buddy systems save lives."],["What is a near-miss?","An incident without injury — reporting them prevents the real thing."]]},{"title":"Measurement and Instrumentation","brief":"Choosing and using instruments so numbers mean what you think they mean.","points":["Match instrument range and resolution to the measurement need.","Accuracy is closeness to truth; precision is repeatability.","Every instrument needs calibration against standards.","Record raw readings with units — never trust memory."],"examples":["Choosing a 0.1-mg balance for analytical work, not a kitchen scale.","A thermocouple's ice-point check before critical temperature runs."],"history":["19th-century metrology built the measurement science base.","The 1960 SI system unified units globally."],"uses":["Metrologists maintain the world's measurement standards.","QC labs calibrate the instruments industry trusts.","Researchers select instruments during experimental design."],"qa":[["Accuracy vs precision?","Accuracy hits the bullseye; precision groups tightly — you need both."],["How often calibrate?","Per drift risk and criticality — typically 6-12 months."],["Digital vs analog?","Digital for readability; analog for trends — both need calibration."]]},{"title":"Data Collection Methods","brief":"Gathering observations systematically — the bridge between design and analysis.","points":["Standardize procedures so every data point is comparable.","Automate where possible — loggers beat clipboards for volume and honesty.","Record metadata: who, when, conditions, instrument, settings.","Back up continuously — data loss is the unforgivable sin."],"examples":["A datalogger recording reactor temperatures every second.","A standardized field form ensuring every surveyor records the same fields."],"history":["20th-century industrial statistics built data-collection discipline.","The 2000s-10s sensor revolution automated collection."],"uses":["Field scientists design collection protocols.","Clinical trials use electronic data capture.","Manufacturers collect SPC data on lines."],"qa":[["Paper or electronic?","Electronic with validation — paper invites transcription errors."],["How to handle missing data?","Document why; never silently fill — analysis must account for it."],["What is ALCOA?","Attributable, Legible, Contemporaneous, Original, Accurate — data integrity."]]},{"title":"Observational Studies","brief":"Learning from the world as it is — when experiments are impossible or unethical.","points":["Cohort studies follow groups over time; case-control looks backward from outcomes.","Confounding is the constant threat — adjust with statistics or design.","Large samples and careful measurement compensate for no randomization.","They generate hypotheses and sometimes the only ethical evidence."],"examples":["Framingham Heart Study linking smoking to heart disease observationally.","Astronomers studying supernovae they can never manipulate."],"history":["19th-century epidemiology (Snow, Farr) founded observational methods.","1950s smoking studies proved observational evidence can be decisive."],"uses":["Epidemiologists track disease causes and risks.","Economists study policies as natural experiments.","Ecologists observe systems too big to manipulate."],"qa":[["Can observation prove causation?","Rarely alone — but strong, consistent, dose-response evidence convinces."],["What's the main weakness?","Confounding — the unmeasured differences between groups."],["Why not always experiment?","Ethics, scale, and cost — you can't randomize smoking or earthquakes."]]},{"title":"Surveys and Questionnaires","brief":"Asking systematically — designing questions that yield honest, usable answers.","points":["Define the population and sample representatively — convenience samples mislead.","Question wording shapes answers — pilot-test for bias and confusion.","Response scales (Likert) need consistent anchors and direction.","Nonresponse bias: the people who don't answer differ from those who do."],"examples":["A customer survey's leading question inflating satisfaction scores.","A health survey's careful wording getting honest sensitive answers."],"history":["1930s-40s polling science (Gallup, Roper) built survey methodology.","The 1948 Dewey polling failure taught humility about sampling."],"uses":["Market researchers survey customers and voters.","Social scientists measure attitudes and behaviors.","Evaluators survey program participants."],"qa":[["How many responses needed?","Depends on desired precision — ~400 for ±5% at 95% confidence."],["Online surveys valid?","With proper panels and weighting — convenience clicks aren't."],["Biggest question-design sin?","Leading and double-barreled questions."]]},{"title":"Field Experiments","brief":"Running experiments outside the lab — realism at the cost of control.","points":["Randomize plots, sites, or subjects as the design allows.","Blocking by location/soil/weather tames environmental noise.","Expect attrition — weather, animals, and people disrupt plans.","Document conditions obsessively; the field won't repeat itself."],"examples":["Randomized fertilizer plots across a farm's soil gradient.","A restored wetland's experimental planting treatments."],"history":["Rothamsted's 1843 field trials are the longest-running experiments on Earth.","Ecological field experiments matured in the 1960s-80s."],"uses":["Agronomists test varieties and practices in real fields.","Ecologists manipulate plots to test theory.","Restorationists trial techniques before scaling."],"qa":[["Lab or field?","Lab for mechanism, field for reality — do both when possible."],["How to handle weather?","Replicate across years; weather is the ultimate uncontrollable."],["What about edge effects?","Buffer zones around plots prevent contamination."]]},{"title":"Natural Experiments","brief":"Exploiting nature's and society's accidents as experiments — when the world randomizes for you.","points":["Look for as-if random assignment: lotteries, borders, policy cutoffs.","Regression discontinuity exploits thresholds (e.g., test-score cutoffs).","Difference-in-differences compares changes across affected and unaffected groups.","Validate the 'as-if random' claim — it's the whole foundation."],"examples":["Studying draft-lottery effects on lifetime earnings.","Comparing pollution health on either side of a policy boundary."],"history":["Economists (1980s-90s) made natural experiments respectable.","The 2021 Nobel Prize honored natural-experiment methods."],"uses":["Economists evaluate policies without RCTs.","Epidemiologists study disasters' health effects.","Political scientists study electoral rules' consequences."],"qa":[["Are they as good as RCTs?","When the as-if-random claim holds, nearly — always scrutinize it."],["What's the catch?","You can't choose the treatment or guarantee balance."],["Examples?","Lotteries, weather shocks, arbitrary borders and cutoffs."]]},{"title":"Quasi-Experimental Design","brief":"Rigorous without randomization — matching, time series, and careful comparison.","points":["Nonequivalent control groups: compare, then adjust for pre-existing differences.","Interrupted time series: many measurements before and after the intervention.","Propensity-score matching mimics randomization statistically.","Threats to validity (history, maturation, selection) must each be addressed."],"examples":["A school's new curriculum compared to a matched school's scores.","Monthly accident rates before and after a speed-limit change."],"history":["Campbell and Stanley's 1963 designs codified quasi-experimentation.","1970s-80s program evaluation made it the standard toolkit."],"uses":["Evaluators assess programs that can't be randomized.","Educators test interventions in real schools.","Policy analysts compare jurisdictions."],"qa":[["Quasi vs true experiment?","No random assignment — weaker causal claims, often the only option."],["How to strengthen them?","Multiple baselines, matched controls, and ruling out alternatives."],["Are they publishable?","Yes — with transparent discussion of validity threats."]]},{"title":"Factorial Design","brief":"Testing multiple factors at once — and catching their interactions.","points":["A 2x2 design tests two factors at two levels each in four runs.","Interactions — when factors combine non-additively — are the prize.","Fractional factorials screen many factors with few runs.","Center points check for curvature and provide error estimates."],"examples":["Testing temperature AND pressure together, finding they interact.","A 2^3 design screening three formulation factors in eight runs."],"history":["Fisher's 1920s factorial insight revolutionized agricultural trials.","Box and colleagues (1950s-70s) built industrial factorial methods."],"uses":["Process engineers optimize multiple parameters simultaneously.","Formulators screen ingredients efficiently.","Marketers test message combinations."],"qa":[["Why not one-factor-at-a-time?","It misses interactions and wastes runs — factorials dominate."],["What is confounding in fractionals?","Some effects alias together — choose fractions that alias the unimportant."],["How many factors?","Screen many in fractionals, then optimize the vital few."]]},{"title":"Design of Experiments (DOE)","brief":"The industrial statistics of efficient experimentation — screening, optimizing, robustifying.","points":["Screening designs find the vital few factors among many suspects.","Response-surface designs map optima precisely.","Robust parameter design makes processes insensitive to noise.","Sequential experimentation: learn, then design the next round."],"examples":["A chemical plant's DOE doubling yield in 20 runs.","A Taguchi array making a process immune to raw-material variation."],"history":["Fisher (agriculture) → Box (industry, 1950s) → Taguchi (quality, 1980s).","Six Sigma (1990s-2000s) put DOE in every black belt's toolkit."],"uses":["Manufacturing optimizes processes and formulations.","R&D develops products faster with fewer prototypes.","Quality engineers solve chronic variation problems."],"qa":[["DOE vs trial-and-error?","DOE finds optima in dozens of runs; trial-and-error takes hundreds."],["What software?","Minitab, JMP, Design-Expert, or Python/R libraries."],["Biggest DOE mistake?","Skipping the planning — garbage factors in, garbage optimum out."]]},{"title":"Response Surface Methodology","brief":"Mapping the hilltop — finding optimal settings with curved models.","points":["Central composite and Box-Behnken designs sample the region efficiently.","Quadratic models capture curvature and locate optima.","Contour plots visualize the response landscape.","Confirm the predicted optimum with verification runs."],"examples":["Mapping a reaction's yield hilltop in temperature-pressure space.","A Box-Behnken design optimizing a tablet formulation."],"history":["Box and Wilson's 1951 paper founded RSM.","The 1960s-80s refined designs for industry."],"uses":["Chemists optimize reactions and formulations.","Food scientists tune processes for quality.","Engineers balance competing responses with desirability functions."],"qa":[["How is RSM different from factorials?","Factorials screen; RSM maps curvature near the optimum."],["What if the optimum is outside?","Steepest ascent moves the region, then RSM maps it."],["Multiple responses?","Overlay contours or use desirability functions."]]},{"title":"Taguchi Methods","brief":"Genichi Taguchi's robust-design philosophy — quality through insensitivity to noise.","points":["Control factors (settable) vs noise factors (uncontrollable).","Orthogonal arrays test many factors in few runs.","Signal-to-noise ratios measure robustness, not just average performance.","The loss function quantifies quality as deviation from target."],"examples":["An orthogonal array finding settings immune to humidity variation.","A design whose performance barely shifts across suppliers."],"history":["Taguchi's 1980s methods transformed Japanese manufacturing quality.","Western adoption (late 1980s-90s) sparked fierce statistical debates."],"uses":["Automotive and electronics design robust products.","Process engineers desensitize processes to variation.","Quality teams apply loss-function thinking to tolerances."],"qa":[["Taguchi vs classical DOE?","Taguchi emphasizes robustness to noise; classical emphasizes effect estimation."],["Are orthogonal arrays efficient?","Very for screening — the statistics community refined the analysis."],["What is the loss function?","Quality loss grows with the square of deviation from target."]]},{"title":"A/B Testing","brief":"The internet's experiment engine — randomized tests of web, product, and marketing changes.","points":["Randomly split users; measure the metric that matters.","Pre-register the hypothesis, metric, and runtime.","Watch for peeking — checking early inflates false positives.","Segment results, but beware multiple-comparison traps."],"examples":["Testing two checkout buttons' conversion rates.","An email subject-line test on 10% of the list."],"history":["1990s direct marketing; 2000s Google/Amazon made online A/B ubiquitous.","The 2010s brought multi-armed bandits and always-on testing."],"uses":["Product teams test features before full rollout.","Marketers optimize campaigns and pricing.","Growth teams run experimentation programs."],"qa":[["How long to run?","Until powered — usually 1-2 full weekly cycles minimum."],["What is a bandit?","Adaptive allocation favoring winners during the test."],["Why did my test fail?","Weak hypothesis, wrong metric, or insufficient power — diagnose, don't just rerun."]]},{"title":"Clinical Trial Design","brief":"Testing medicines in humans — phases, ethics, and the highest experimental stakes.","points":["Phase I: safety in dozens; Phase II: efficacy signals in hundreds; Phase III: confirmation in thousands.","Randomized, double-blind, controlled — the regulatory gold standard.","Endpoints must be clinically meaningful and pre-specified.","Ethics boards and informed consent protect participants."],"examples":["A Phase III trial's 10,000 patients proving a vaccine's efficacy.","An adaptive trial dropping losing arms early."],"history":["1948 streptomycin trial; 1962 Kefauver-Harris Amendments mandated efficacy proof.","The 2000s-10s brought adaptive designs and master protocols."],"uses":["Pharma and biotech develop drugs through trials.","Academic medical centers run investigator-initiated studies.","Regulators (FDA, EMA) judge approvals on trial data."],"qa":[["Why do trials take so long?","Recruitment, follow-up, and safety monitoring can't be rushed."],["What is an adaptive trial?","Pre-planned modifications based on interim data — efficient and ethical."],["Can I join a trial?","ClinicalTrials.gov lists recruiting studies by condition and location."]]},{"title":"Animal Study Design","brief":"Ethical, statistically sound experiments with animal models.","points":["The 3Rs: Replace, Reduce, Refine — the ethical framework.","Choose models with translational relevance to the question.","Randomize, blind, and power studies like any experiment.","IACUC approval is required before starting."],"examples":["A mouse study's randomized cage assignments preventing rack-position bias.","Blinded scoring of tissue samples."],"history":["19th-century physiology; 1959 Russell and Burch's 3Rs.","The 2010s reproducibility push exposed poor animal-study design."],"uses":["Biomedical researchers test mechanisms and therapies.","Toxicologists assess chemical safety.","Veterinary researchers improve animal health."],"qa":[["Why still use animals?","Whole-organism biology can't yet be fully replaced — alternatives grow yearly."],["Biggest design flaw?","Underpowered studies with unblinded subjective scoring."],["What is ARRIVE?","Reporting guidelines making animal studies transparent and reproducible."]]},{"title":"Cell Culture Experiments","brief":"Growing cells in dishes — the controlled biology workhorse.","points":["Sterile technique prevents contamination — the eternal battle.","Cell lines vs primary cells: convenience vs relevance.","Passage number, confluency, and media affect every result.","Mycoplasma testing — invisible contamination ruins experiments."],"examples":["A dose-response curve from a 96-well plate reader.","Contamination traced to a shared media bottle."],"history":["1950s HeLa and tissue-culture methods enabled modern cell biology.","The 2000s-10s brought 3D organoids and CRISPR screens."],"uses":["Drug discovery screens compounds in cells first.","Toxicologists test without animals where possible.","Basic researchers probe mechanisms in controlled systems."],"qa":[["Why did my cells die?","Contamination, wrong media, overgrowth — check systematically."],["Cell line authentication?","Misidentified lines wasted decades — STR-profile your lines."],["2D vs 3D culture?","3D organoids mimic tissues better; 2D is cheaper and higher-throughput."]]},{"title":"Chemistry Bench Techniques","brief":"The hands-on craft of the chemistry lab — pure substances, clean reactions, safe handling.","points":["Weigh, dissolve, mix, heat, cool, separate — the fundamental operations.","Purity matters: recrystallization, distillation, and chromatography purify.","Inert atmospheres protect air-sensitive reactions.","Waste segregation keeps disposal safe and legal."],"examples":["A recrystallization's crystals forming as the flask cools.","A Schlenk line's nitrogen blanket protecting an organometallic reaction."],"history":["19th-century organic chemistry built the bench toolkit.","The 1900s-2000s added spectroscopy-guided synthesis."],"uses":["Synthetic chemists make new molecules.","Analytical chemists prepare samples for instruments.","Students learn technique before theory sticks."],"qa":[["Why won't it crystallize?","Too impure, wrong solvent, or too fast — scratch, seed, or change solvent."],["Biggest beginner mistake?","Poor notebook records making successes unrepeatable."],["How to stay safe?","Know every reagent's hazards; never scale up blindly."]]},{"title":"Titration","brief":"The classic quantitative analysis — measuring concentration drop by drop.","points":["A burette delivers titrant to the analyte until the endpoint.","Indicators (phenolphthalein) or pH meters signal the endpoint.","Stoichiometry converts titrant volume to analyte concentration.","Standardized titrants and replicate titrations ensure accuracy."],"examples":["An acid-base titration's pink flash marking neutralization.","A redox titration determining iron in a supplement."],"history":["19th-century volumetric analysis; still the teaching-lab standard.","Autotitrators (1970s+) automated the technique."],"uses":["QC labs assay raw materials and products.","Environmental labs measure alkalinity and chlorine.","Students learn quantitative technique hands-on."],"qa":[["Overshot the endpoint?","Note it, learn the approach speed, and retitrate."],["Indicator or pH meter?","Meters are more objective; indicators are faster for routine work."],["How precise?","0.1% with care — still competitive with instruments for some assays."]]},{"title":"Spectroscopy Basics","brief":"Reading light's interaction with matter to identify and quantify substances.","points":["Absorption, emission, and scattering each reveal structure.","Beer-Lambert law: absorbance is proportional to concentration.","UV-Vis suits conjugated organics; IR identifies functional groups.","NMR and MS give definitive structures."],"examples":["An IR spectrum's carbonyl peak identifying an unknown.","A UV-Vis calibration curve quantifying a dye."],"history":["19th-century flame tests; 1940s-60s commercial spectrometers.","FTIR, NMR, and MS became routine by the 1980s-90s."],"uses":["Analytical labs identify unknowns and verify purity.","Process analyzers monitor streams in real time.","Forensics matches spectra to databases."],"qa":[["Which technique when?","IR for functional groups, NMR/MS for structure, UV-Vis for concentration."],["What is a blank?","The solvent-only reference — subtract it or fool yourself."],["Can spectra lie?","Mixtures and bad baselines mislead — separate and calibrate."]]},{"title":"Chromatography Basics","brief":"Separating mixtures by differential migration — the analyst's workhorse.","points":["Mobile phase carries the sample through a stationary phase.","Different affinities separate components into peaks.","GC suits volatiles; HPLC suits non-volatiles; TLC screens fast.","Retention times identify; peak areas quantify."],"examples":["A GC trace separating a fuel's hydrocarbon fingerprint.","A TLC plate showing a reaction's progress in minutes."],"history":["Tswett's 1903 plant-pigment columns; 1950s-60s GC/HPLC revolution.","UHPLC (2000s) doubled speed and resolution."],"uses":["Pharma QC, environmental testing, and forensics run on chromatography.","Food labs verify purity and detect adulteration.","Researchers purify compounds for study."],"qa":[["GC or HPLC?","Volatile and thermally stable → GC; otherwise HPLC."],["What ruins columns?","Dirty samples, wrong pH, and pressure shocks — filter and guard."],["How to quantify?","Calibrate with standards; internal standards correct injection variation."]]},{"title":"Microscopy Techniques","brief":"Seeing the small — light, electron, and probe microscopes.","points":["Light microscopy: cheap, live samples, ~200-nm resolution limit.","SEM images surfaces at nanometers; TEM sees through ultra-thin sections.","Fluorescence tags specific structures with glowing labels.","Sample prep (fixation, coating, sectioning) often matters more than the scope."],"examples":["Fluorescence lighting up a cell's cytoskeleton.","An SEM image revealing a fracture's origin."],"history":["1590s first microscopes; 1930s electron microscopes; 1980s scanning probes.","Super-resolution (2010s) broke the light limit — Nobel 2014."],"uses":["Biologists image cells and tissues.","Materials scientists study fractures and microstructures.","Failure analysts find the flaw that broke it."],"qa":[["What magnification do I need?","Match to the feature — empty magnification adds nothing."],["Why coat SEM samples?","Non-conductive samples charge — metal coating bleeds it off."],["Live or fixed?","Live for dynamics; fixed for detail — pick by question."]]},{"title":"Physics Lab Experiments","brief":"Testing nature's laws with apparatus — mechanics to electromagnetism to optics.","points":["Start with the prediction: what does theory say, quantitatively?","Design apparatus to isolate the effect from friction, noise, and drift.","Estimate uncertainties before measuring — design to beat them.","Compare result to theory with error bars, not vibes."],"examples":["Timing a pendulum to measure g within 1%.","Mapping equipotentials to visualize electric fields."],"history":["Galileo's inclined planes; 19th-century precision labs; 20th-century undergraduate labs.","Modern labs add computer interfacing and video analysis."],"uses":["Students learn measurement and uncertainty hands-on.","Researchers prototype tabletop tests of new ideas.","Metrologists refine fundamental constants."],"qa":[["Why repeat measurements?","Random error shrinks as 1/sqrt(n) — averaging works."],["Systematic vs random error?","Systematic biases every reading; random scatters — hunt both."],["My result disagrees with theory — now what?","Check apparatus and analysis thrice before claiming new physics."]]},{"title":"Electronics Bench Testing","brief":"Proving circuits work — power supplies, scopes, meters, and methodical debugging.","points":["Power up gradually: current-limited supplies catch shorts safely.","Oscilloscopes reveal what multimeters hide — timing, noise, distortion.","Divide and conquer: test stages independently to isolate faults.","Document expected vs measured at every test point."],"examples":["A scope trace revealing a noisy power rail crashing a microcontroller.","A current-limited supply saving a board from a solder bridge."],"history":["1950s-60s transistor labs; 1970s-80s digital test gear.","Modern mixed-signal scopes debug entire systems."],"uses":["Design engineers validate prototypes.","Technicians troubleshoot production failures.","Hobbyists learn electronics hands-on."],"qa":[["Where to start debugging?","Power rails first — most faults are power."],["Why is my circuit oscillating?","Usually layout, decoupling, or feedback — scope the rails."],["ESD precautions?","Mats, straps, and grounded tools for sensitive parts."]]},{"title":"Materials Testing","brief":"Breaking things on purpose — tensile, hardness, impact, and fatigue.","points":["Tensile tests give strength, ductility, and modulus from one pull.","Hardness (Rockwell, Brinell, Vickers) estimates strength quickly.","Charpy impact tests toughness at temperature — the Titanic lesson.","Fatigue testing predicts life under cyclic loads."],"examples":["A tensile bar necking before fracture, plotting the stress-strain curve.","A Charpy specimen shattering at -40 F, passing at room temp."],"history":["19th-century rail breaks drove standardized testing.","ASTM/ISO standards (1900s-2000s) made results comparable worldwide."],"uses":["Engineers qualify materials for designs.","QC labs verify incoming stock and heat treatment.","Failure analysts test exemplars against failed parts."],"qa":[["Why test at temperature?","Toughness collapses at low temperature for many steels."],["Hardness vs strength?","Correlated for steel — hardness is the quick shop check."],["What is fatigue limit?","The stress below which steel lasts indefinitely — aluminum has none."]]},{"title":"Environmental Sampling Design","brief":"Collecting representative environmental samples — where, when, and how many.","points":["Define data quality objectives before sampling.","Stratify by expected variation — don't average away hotspots.","Consider temporal variation: storms, seasons, and operating cycles.","Chain of custody and preservation protect sample integrity."],"examples":["Storm-chasing autosamplers catching a river's first flush.","A stratified soil grid finding the hot spot random sampling missed."],"history":["1970s-80s EPA methods standardized environmental sampling.","The 1990s-2000s added statistical design (DQO process)."],"uses":["Consultants design sampling for investigations.","Regulators specify monitoring in permits.","Researchers sample ecosystems representatively."],"qa":[["Grab or composite?","Grabs catch peaks; composites average — match to the question."],["How many samples?","Enough for the statistics — power and confidence decide."],["Can I sample after rain?","Only if that's the condition you're studying — document it."]]},{"title":"Statistical Analysis Basics","brief":"Turning data into decisions — description, inference, and honest uncertainty.","points":["Describe first: means, medians, spreads, and plots.","Inferential tests generalize from sample to population.","Assumptions (normality, independence) must be checked, not assumed.","Effect sizes matter more than p-values."],"examples":["A boxplot revealing the outlier driving a 'significant' result.","A confidence interval showing an effect too small to matter."],"history":["1900s-30s: Gosset, Fisher, Neyman-Pearson built the toolkit.","The 2010s reproducibility crisis reformed statistical practice."],"uses":["Scientists analyze experiments in every field.","Business analysts test changes with statistics.","Regulators judge safety and efficacy on statistical evidence."],"qa":[["What is a p-value?","The probability of data this extreme if the null were true — not the probability the hypothesis is true."],["Parametric or non-parametric?","Parametric when assumptions hold; non-parametric when they don't."],["Should I remove outliers?","Only with documented cause — otherwise analyze with and without."]]},{"title":"Hypothesis Testing and P-Values","brief":"The formal machinery of deciding whether data supports an effect.","points":["State null and alternative hypotheses before seeing data.","Choose alpha (usually 0.05) — the false-positive rate you'll accept.","Compute the test statistic and its p-value under the null.","Reject or fail to reject — never 'accept' the null."],"examples":["A t-test's p=0.003 rejecting no-difference between treatments.","A p=0.4 correctly failing to claim an underpowered effect."],"history":["Fisher (1920s) vs Neyman-Pearson (1930s) — the great synthesis and its confusions.","The 2010s ASA statement clarified p-value misuse."],"uses":["Every experimental science tests hypotheses.","Clinical trials live or die on pre-specified tests.","Quality engineers test process changes."],"qa":[["What does p=0.05 mean?","A 5% false-positive rate under the null — not 95% chance the effect is real."],["Why pre-register?","To prevent choosing the test that gives the desired answer."],["Alternatives to p-values?","Confidence intervals, Bayes factors, and effect sizes."]]},{"title":"Confidence Intervals","brief":"Ranges that quantify uncertainty — more informative than p-values alone.","points":["A 95% CI contains the true value in 95% of repeated experiments.","Width reflects precision — narrower means more informative.","CIs show both statistical and practical significance.","They're dual to hypothesis tests but richer."],"examples":["A drug's effect: 8 points (95% CI: 2 to 14) — real but imprecise.","Overlapping CIs correctly tempering a 'difference' claim."],"history":["Neyman's 1930s confidence concept; popularized as p-value alternative in the 1980s-2010s.","Medical journals now require CIs (CONSORT)."],"uses":["Researchers report effects with uncertainty.","Engineers tolerance their designs from intervals.","Pollsters' margins of error are confidence intervals."],"qa":[["What if the CI includes zero?","The effect isn't statistically distinguishable from zero."],["95% or 99%?","95% standard; 99% when false positives are costly."],["CI vs prediction interval?","CI for the mean; prediction interval for the next observation — wider."]]},{"title":"Regression Analysis","brief":"Modeling relationships — predicting outcomes from predictors.","points":["Simple regression fits a line; multiple regression handles many predictors.","Coefficients estimate each predictor's effect holding others constant.","R-squared measures fit; residual plots diagnose problems.","Correlation isn't causation — design, not math, establishes cause."],"examples":["A calibration curve's regression converting signal to concentration.","Residual plots revealing a nonlinear relationship a straight line missed."],"history":["Legendre/Gauss (1800s) least squares; Galton's 1880s regression concept.","20th-century statistics made regression the default analysis."],"uses":["Scientists model dose-response and calibrations.","Economists estimate policy effects.","Engineers build empirical process models."],"qa":[["What ruins regression?","Outliers, nonlinearity, multicollinearity, and extrapolating beyond data."],["How many predictors?","Roughly 10-15 observations per predictor minimum."],["Linear or nonlinear?","Start linear; let residual plots demand curves."]]},{"title":"ANOVA","brief":"Comparing multiple groups — the analysis of variance behind designed experiments.","points":["ANOVA partitions variation into treatment vs random error.","The F-test asks whether group differences exceed noise.","Post-hoc tests (Tukey) identify which groups differ — with error control.","Two-way ANOVA tests two factors and their interaction."],"examples":["A one-way ANOVA comparing four fertilizers' yields.","Tukey's test pinpointing which fertilizer beats the control."],"history":["Fisher's 1920s ANOVA for agricultural trials.","The standard analysis for designed experiments ever since."],"uses":["Researchers compare treatments across groups.","Quality engineers analyze factor effects.","Psychologists compare conditions."],"qa":[["ANOVA or t-tests?","ANOVA for 3+ groups — multiple t-tests inflate false positives."],["What are the assumptions?","Normality, equal variance, independence — check residuals."],["Significant ANOVA — done?","No — post-hocs tell you where the differences are."]]},{"title":"Error Analysis and Uncertainty","brief":"Quantifying doubt — every measurement needs its ±.","points":["Random errors scatter; systematic errors bias — treat differently.","Propagate uncertainties through calculations properly.","Report results as value ± uncertainty with units.","The GUM framework standardizes uncertainty evaluation."],"examples":["A density's uncertainty propagated from mass and volume errors.","A calibration's uncertainty budget dominating a QC decision."],"history":["19th-century least squares; 1993 GUM standardized uncertainty.","Modern labs report uncertainties on every certified value."],"uses":["Metrologists certify reference values with uncertainties.","Engineers tolerance designs against uncertainty.","Regulators judge compliance considering measurement doubt."],"qa":[["How many significant figures?","Match the uncertainty — usually 1-2 in the uncertainty."],["What is a coverage factor?","k=2 gives ~95% confidence for the expanded uncertainty."],["Can uncertainty be reduced?","Random: average more. Systematic: better methods and calibration."]]},{"title":"Outliers and Data Cleaning","brief":"Handling the weird points — honestly, not conveniently.","points":["Define outlier criteria before seeing data.","Investigate causes — instrument glitches, transcription, real phenomena.","Document every exclusion or correction.","Analyze with and without questionable points (sensitivity analysis)."],"examples":["A 10x transcription error caught by range checks.","A genuine extreme event kept and reported transparently."],"history":["19th-century astronomers debated rejecting observations.","Modern guidelines demand pre-specified, documented cleaning."],"uses":["Data scientists clean before modeling.","QC analysts investigate out-of-spec points.","Auditors check cleaning logs for bias."],"qa":[["When can I delete an outlier?","With documented assignable cause — never just for convenience."],["What about imputation?","For missing data with proper methods — never fabricate."],["Automated cleaning?","Flag, don't auto-delete — human judgment on exclusions."]]},{"title":"Data Visualization","brief":"Showing data honestly — plots that reveal truth instead of hiding it.","points":["Choose the plot for the question: distributions, relationships, comparisons, trends.","Show the data, not just summaries — boxplots and dot plots beat bar charts of means.","Honest axes: zero baselines for bars, no truncated trickery.","Annotate directly; minimize chartjunk."],"examples":["A scatter plot revealing the nonlinearity a correlation hid.","Small multiples comparing treatments at a glance."],"history":["Playfair's 1780s charts; Tukey's 1970s exploratory data analysis.","Tufte (1980s) and the 2010s dataviz renaissance."],"uses":["Scientists explore and present with plots.","Analysts dashboard KPIs.","Journalists communicate data to the public."],"qa":[["Best plot for distributions?","Histograms, boxplots, violin plots — show shape, not just means."],["3D charts?","Almost never — they distort perception."],["What is chartjunk?","Decoration that obscures data — remove it."]]},{"title":"Lab Notebooks and Documentation","brief":"The written record that makes science reproducible — and defensible.","points":["Record contemporaneously: date, purpose, procedure, observations, results.","Mistakes get single-line cross-outs, never erasure.","Electronic notebooks need validation, backups, and access controls.","Notebooks are legal documents in patent and fraud disputes."],"examples":["A dated entry letting a colleague repeat an experiment exactly.","A notebook page proving invention priority in a patent case."],"history":["19th-century bound notebooks; 2000s-10s electronic lab notebooks.","FDA/patent rules shaped documentation standards."],"uses":["Researchers document for reproducibility and IP.","Regulated labs follow ALCOA data-integrity principles.","Students learn the habit that defines professionals."],"qa":[["Paper or electronic?","Electronic with proper controls; paper still fine with discipline."],["What must every entry have?","Date, purpose, method, raw data, observations, conclusion."],["Can I tear out pages?","Never — bound, paginated, permanent."]]},{"title":"Reproducibility Crisis","brief":"Science's reckoning — why so many findings don't replicate, and the reforms fixing it.","points":["Underpowered studies, p-hacking, and publication bias manufactured false positives.","Famous failures: psychology, cancer biology, and social priming replications.","Reforms: preregistration, open data, registered reports, bigger samples.","Replication is now a valued contribution, not a insult."],"examples":["The 2015 psychology replication project: only ~40% replicated.","A registered report getting published regardless of outcome."],"history":["2011-2015: Bem, priming failures, and Ioannidis's 'why most findings are false'.","The 2010s-20s reform movement: TOP guidelines, open science."],"uses":["Funders require data sharing and preregistration.","Journals offer registered reports.","Meta-scientists study science itself."],"qa":[["Is science broken?","No — it's self-correcting, and the correction is underway."],["What is preregistration?","Locking hypotheses and analysis plans before data collection."],["Should I trust single studies?","Treat them as preliminary until replicated."]]},{"title":"Peer Review","brief":"Science's quality filter — critical evaluation by experts before publication.","points":["Reviewers check methods, analysis, interpretation, and novelty.","Single/double-blind models balance accountability and bias.","Revise-and-resubmit improves most papers substantially.","Post-publication review continues on preprints and social media."],"examples":["A reviewer's catch of a statistical error saving a paper from embarrassment.","A preprint's comments improving the final journal version."],"history":["1665 Royal Society; 20th-century universal pre-publication review.","The 2010s-20s: preprints, open review, and review reform."],"uses":["Journals gatekeep the literature.","Grant agencies peer-review funding decisions.","Researchers review as professional duty."],"qa":[["Is peer review reliable?","Imperfect but the best filter we have — fraud still slips through."],["How to handle harsh reviews?","Extract the valid criticism; rebut the rest professionally."],["What is open review?","Signed, published reviews — accountability over anonymity."]]},{"title":"Ethics in Experimentation","brief":"The moral boundaries of research — consent, welfare, and honesty.","points":["Human subjects: informed consent, risk minimization, IRB review.","Animal research: the 3Rs and IACUC oversight.","Research integrity: no fabrication, falsification, or plagiarism.","Dual-use and environmental concerns shape what's permissible."],"examples":["An IRB requiring consent-form revisions before a study proceeds.","A lab's data-integrity training after a fabrication scandal."],"history":["Nuremberg (1947) and Helsinki (1964) for humans; 3Rs (1959) for animals.","2000s-10s misconduct cases drove integrity offices and training."],"uses":["IRBs and IACUCs review protocols.","Research integrity officers investigate misconduct.","Everyone with a lab coat needs ethics training."],"qa":[["What is fabrication?","Making up data — the cardinal sin, career-ending."],["Can I use leftover clinical samples?","Only with consent and IRB approval."],["Who owns the data?","Typically the institution — know your agreements."]]},{"title":"Troubleshooting Failed Experiments","brief":"When nothing works — the systematic art of finding what's wrong.","points":["Reproduce the failure reliably before fixing anything.","Change one variable at a time; document each test.","Check the basics first: reagents, calibration, power, connections.","Consult the literature and colleagues — someone has seen this."],"examples":["A dead PCR traced to a degraded primer stock.","An intermittent fault caught by wiggling connectors systematically."],"history":["Every experimentalist's apprenticeship is troubleshooting school.","Edison's famous thousands of 'ways that won't work'."],"uses":["Researchers debug daily — it's most of the job.","Field engineers troubleshoot under pressure.","Manufacturing uses structured methods (8D, 5 Whys)."],"qa":[["Where do I start?","Verify the simplest assumptions first — fresh reagents, correct settings."],["How do I stay sane?","Log everything; take breaks; ask for fresh eyes."],["When to quit an approach?","When systematic tests rule out the mechanism, not from frustration."]]},{"title":"Calibration Curves and Standards","brief":"Turning instrument signals into concentrations — the quantitative backbone of analysis.","points":["Standards of known concentration bracket the expected range.","Linear regression converts signal to concentration; check linearity (R², residuals).","Matrix-matched standards and internal standards correct for interference.","Recalibrate on schedule — drift invalidates old curves."],"examples":["A five-point curve converting absorbance to protein concentration.","An internal standard correcting injection variation in GC runs."],"history":["19th-century volumetric standards; 20th-century instrumental calibration.","Certified reference materials (NIST) anchor global comparability."],"uses":["Analytical labs calibrate every quantitative method.","Field kits include standards for on-site verification.","Regulators require calibration records for compliance data."],"qa":[["How many standards?","At least 5 spanning the range, plus blanks."],["What is standard addition?","Spiking the sample itself — correcting for matrix effects."],["When to recalibrate?","Per method schedule, and whenever QC fails."]]},{"title":"Assay Controls","brief":"The built-in checks that prove a test worked — positive, negative, and blank controls.","points":["Positive controls verify the assay detects what it should.","Negative controls verify no false signal without analyte.","Blanks measure background to subtract.","Controls run with every batch — a batch without controls is uninterpretable."],"examples":["A PCR's positive control band proving the reaction worked.","An ELISA's blank wells setting the background threshold."],"history":["Early 20th-century serology formalized control sera.","Modern diagnostics require controls by regulation (CLIA, ISO)."],"uses":["Clinical labs validate every run with controls.","Manufacturers QC-test with control charts.","Researchers include controls reviewers demand."],"qa":[["What if controls fail?","The whole batch is invalid — troubleshoot, don't cherry-pick."],["How many controls?","At minimum one positive and one negative per batch."],["Can controls be faked?","Only by fraud — LIMS audit trails and inspections deter it."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-experiment-solver-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('experiment-solver',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();